{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C46"],
      "claim": "Pethidine, which shares the 1-methylpiperidine ester and phenyl pharmacophore with the query, has an absolute oral bioavailability of 0.53 in healthy volunteers, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C45"],
      "claim": "Ebastine, a diphenylmethoxy-piperidine drug with structural similarity to the query, has about 40% oral bioavailability in humans, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C59"],
      "claim": "Bilastine, a piperidine-containing drug, has an absolute oral bioavailability of 61% in healthy adults, supporting high oral bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Fexofenadine, despite being a P-gp substrate with incomplete absorption, has an absolute oral bioavailability of 30 ± 7.9% in humans, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C58"],
      "claim": "Fentanyl, a basic tertiary amine with substantial first-pass metabolism, has an absolute oral bioavailability of 0.31 in healthy volunteers, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "Oxybutynin, a structurally related ester antimuscarinic, has a low absolute oral bioavailability of 6.2 ± 1.2%, which is contradictory; however, its cyclohexyl-hydroxy-alkynyl-diethylamino structure confers much greater first-pass liability than the query's propoxy-diphenyl-piperidinyl ester, so this low value transfers poorly.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a propiverine-like 1-methylpiperidin-4-yl 2,2-diphenyl-2-propoxyacetate. Most transferable human absolute-bioavailability evidence from structurally related piperidine ester and antimuscarinic drugs (pethidine ~50%, ebastine ~40%, bilastine ~61%, fexofenadine ~30%, fentanyl ~31%) supports F >= 20%. The low oxybutynin value (~6%) is the main contradictory anchor, but its structural differences and much higher first-pass metabolism make it a weak counter-transfer. Overall, the evidence favors high oral bioavailability.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself.",
    "No human pharmacokinetic data for propiverine in the provided evidence set.",
    "First-pass metabolism and ester hydrolysis rates for the query are not directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

